<?php use Hls\Http\View as V; $query = $_GET; unset($query['edit']); ?>
<nav class="pagination" aria-label="Pagination"><p><?= (int)$pagination['total'] ?> catatan · Halaman <?= (int)$pagination['page'] ?> dari <?= (int)$pagination['pages'] ?></p><div><?php foreach ([-1 => 'Sebelumnya', 1 => 'Berikutnya'] as $step => $label): $page = $pagination['page'] + $step; ?><?php if ($page < 1 || $page > $pagination['pages']): ?><span class="pagination-disabled" aria-disabled="true"><?= V::escape($label) ?></span><?php else: $query['page'] = $page; ?><a href="<?= V::escape($this->url($this->path() . '?' . http_build_query($query))) ?>"><?= V::escape($label) ?></a><?php endif ?><?php endforeach ?></div></nav>
